import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const documents = ['README.md','ROADMAP.md','PROGRESS.md','ARCHITECTURE.md','SECURITY.md','docs/README.md','docs/OPEN_QUESTIONS.md','docs/VALIDATION.md','docs/phase1/README.md','docs/phase1/INCREMENT_6_1_LOCAL_CLI_FOUNDATION.md'];
const failures: string[] = [];
const sha = (p: string) => new Bun.CryptoHasher('sha256').update(readFileSync(p)).digest('hex');
const clean = (s: string) => s.replace(/```[^\n]*\n[\s\S]*?```/g, '');
const slug = (s: string) => s.toLowerCase().replace(/[`*_~]/g,'').replace(/[^\p{L}\p{N}_\-\s]/gu,'').replace(/\s/g,'-');
let linkCount = 0;
for (const p of documents) {
  const source = readFileSync(p,'utf8');
  if ((source.match(/^```/gm)?.length ?? 0) % 2) failures.push(`Unclosed fence: ${p}`);
  const text = clean(source);
  for (const match of text.matchAll(/\[[^\]\n]+\]\(([^)\n]+)\)/g)) {
    const href = match[1];
    if (/^[a-z][a-z0-9+.-]*:/i.test(href)) continue;
    const [file,anchor] = href.split('#');
    const target = resolve(dirname(p),decodeURIComponent(file || p.split('/').at(-1)!));
    linkCount++;
    if (!existsSync(target)) { failures.push(`Missing local link: ${p} -> ${href}`); continue; }
    if (anchor && target.endsWith('.md')) {
      const ids = [...clean(readFileSync(target,'utf8')).matchAll(/^#{1,6}\s+(.+)$/gm)].map(m=>slug(m[1].trim()));
      if (!ids.includes(decodeURIComponent(anchor))) failures.push(`Missing heading: ${p} -> ${href}`);
    }
  }
}
const requirements = new Set([...readFileSync('REQUIREMENTS.md','utf8').matchAll(/^\| ([FSQ]-\d{2}) \|/gm)].map(m=>m[1]));
for (const id of [...readFileSync(documents.at(-1)!,'utf8').matchAll(/\b[FSQ]-\d{2}\b/g)].map(m=>m[0])) {
  if (!requirements.has(id)) failures.push(`Unknown requirement: ${id}`);
}
const adr = [...new Bun.Glob('docs/adr/000*.md').scanSync('.')].map(p=>p.replaceAll('\\','/')).sort().map(p=>({path:p,status:readFileSync(p,'utf8').match(/^- Status: (.+)$/m)?.[1],sha256:sha(p)}));
const entry = JSON.parse(readFileSync('target/increment61-entry.json','utf8'));
if (adr.length !== 7 || adr.some(a=>a.sha256!==entry.files[a.path])) failures.push('ADR decisions changed or inventory differs');
function git(...args:string[]) { const r = Bun.spawnSync(['git','--no-optional-locks',...args],{stdout:'pipe',stderr:'pipe',env:{...process.env,GIT_OPTIONAL_LOCKS:'0'}}); if(r.exitCode)throw Error(r.stderr.toString());return r.stdout.toString(); }
const blocks = (s:string) => new Map(s.replace(/\r\n/g,'\n').split('[[package]]').slice(1).map(b=>[b.match(/^\s*name = "([^"]+)"/m)![1],b.trim()]));
const before = blocks(git('show','HEAD:Cargo.lock'));
const after = blocks(readFileSync('Cargo.lock','utf8'));
for (const [name,block] of before) if (after.get(name)!==block) failures.push(`Existing lock package changed: ${name}`);
if(after.size!==before.size+1 || !after.has('sentra-cli')) failures.push('Unexpected package inventory');
const cli = readFileSync('crates/sentra-cli/Cargo.toml','utf8');
if (!cli.includes('sentra-core = { path = "../sentra-core", version = "=0.1.0" }')) failures.push('CLI local edge changed');
const production = ['crates/sentra-cli/src/lib.rs','crates/sentra-cli/src/main.rs','crates/sentra-core/src/service/local_workspace.rs'];
for (const p of production) {
  const source = readFileSync(p,'utf8');
  if (/\bunsafe\s*\{|\bunsafe\s+fn|Command::new|std::net|TcpStream|UdpSocket|reqwest|\.execute_task\(/.test(source)) failures.push(`Unexpected unsafe/transport/dispatch code: ${p}`);
}
const currentHead = git('rev-parse','HEAD').trim();
if (!readFileSync(documents.at(-1)!,'utf8').includes(currentHead)) failures.push('Documented HEAD differs');
const report = {increment:'6.1',status:failures.length?'Failed':'Passed',documents:Object.fromEntries(documents.map(p=>[p,sha(p)])),local_links_checked:linkCount,adr,requirement_ids_checked:[...requirements],existing_lock_packages_unchanged:failures.every(f=>!f.includes('lock package')),new_external_packages:0,failures,limitations:['Narrow local-link/fence/heading/ID check, not a full Markdown renderer or runtime egress capture.'],checker_source:readFileSync('target/increment61-documentation.ts','utf8')};
writeFileSync('experiments/phase1/cli/results/61-documentation.json',JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify({status:report.status,documents:documents.length,local_links:linkCount,adrs:adr.length,failures}));
if(failures.length)process.exit(1);
